-- Exemple de base de données: Employees

-- Suppression de la base de données Employees si elle existe déjà.
DROP DATABASE IF EXISTS employees;

-- Création de la base de données Employees.
CREATE DATABASE IF NOT EXISTS employees;

-- Choix de la base de données à utiliser.
USE employees;

-- Affichage d'un message d'information.
SELECT '## Création de la structure de la base de données ##' AS 'INFO 1';

-- Creation des tables.
CREATE TABLE Employees ( -- Table des employés
  emp_no INT NOT NULL, -- Numéro de l'employé
  birth_date DATE NOT NULL, -- Date de naissance de l'employé
  first_name VARCHAR(14) NOT NULL, -- Prénom de l'employé
  last_name VARCHAR(16) NOT NULL, -- Nom de l'employé
  gender CHAR(1) NOT NULL, -- Genre de l'employé
  hire_date DATE NOT NULL, -- Date d'embauche de l'employé
  PRIMARY KEY (emp_no)
);

CREATE TABLE Departments ( -- Table des département
  dept_no CHAR(4) NOT NULL, -- Numéro du département
  dept_name VARCHAR(40) NOT NULL, -- Nom du département
  PRIMARY KEY (dept_no),
  UNIQUE KEY (dept_name)
);

CREATE TABLE Dept_manager ( -- Table associant les manageurs et les départements
  emp_no INT NOT NULL, -- Numéro d'employé du manageur
  dept_no CHAR(4) NOT NULL, -- Numéro du département
  from_date DATE NOT NULL, -- Date à partir de laquelle le département est sous la responsabilité du manageur
  to_date DATE NOT NULL, -- Date au-delà de laquelle, le manageur n'est plus responsable de ce département
  FOREIGN KEY (emp_no) REFERENCES Employees (emp_no),
  FOREIGN KEY (dept_no) REFERENCES Departments (dept_no),
  PRIMARY KEY (emp_no,dept_no)
);

CREATE TABLE Dept_emp ( -- Table associant les employés et les départements
  emp_no INT NOT NULL, -- Numéro d'employé
  dept_no CHAR(4) NOT NULL, -- Numéro du département
  from_date DATE NOT NULL, -- Date à partir de laquelle l'employés fait partie de ce département
  to_date DATE NOT NULL, -- Date à partir de laquelle l'employés ne fait plus partie de ce département
  FOREIGN KEY (emp_no) REFERENCES Employees (emp_no),
  FOREIGN KEY (dept_no) REFERENCES Departments (dept_no),
  PRIMARY KEY (emp_no,dept_no)
);

CREATE TABLE Titles ( -- Table associant les employés et les titres
  emp_no INT NOT NULL, -- Numéro d'employé
  title VARCHAR(50) NOT NULL, -- Titre d'employé
  from_date DATE NOT NULL, -- Date à partir de laquelle ce titre est assigné à l'employé
  to_date DATE, -- Date à partir de laquelle ce titre n'est plus assigné à l'employé
  FOREIGN KEY (emp_no) REFERENCES Employees (emp_no),
  PRIMARY KEY (emp_no,title, from_date)
);

CREATE TABLE Salaries ( -- Table associant les employés et les salaires
  emp_no INT NOT NULL, -- Numéro d'employé
  salary INT NOT NULL, -- Salaire de l'employé
  from_date DATE NOT NULL, -- Date à partir de laquelle l'employé a ce salaire
  to_date DATE NOT NULL, -- Date à partir de laquelle l'employé n'a plus ce salaire
  FOREIGN KEY (emp_no) REFERENCES Employees (emp_no),
  PRIMARY KEY (emp_no, from_date)
);

-- Affichage d'un message d'information.
SELECT '## Insertion des données dans la structure de la base de données ##' AS 'INFO 2';







